def extended_gcd(a, b):
    if a == 0:
        return (b, 0, 1)
    else:
        g, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return (g, x, y)

def mod_inverse(a, m):
    g, x, _ = extended_gcd(a, m)
    if g != 1:
        raise Exception('Modular inverse does not exist')
    else:
        return x % m

def solve_crt(remainders, moduli):
    total = 0
    prod = 1
    for mod in moduli:
        prod *= mod

    for rem, mod in zip(remainders, moduli):
        p = prod // mod
        inv = mod_inverse(p, mod)
        total += rem * inv * p

    return total % prod

